css:
:root {
  --bg: #0D1117;
  --card: #141E2B;
  --card2: #1A2535;
  --line: rgba(255,255,255,.07);
  --line2: rgba(255,255,255,.12);
  --t1: #FFFFFF;
  --t2: rgba(255,255,255,.76);
  --t3: rgba(255,255,255,.52);
  --blue: #6B9FFF;
  --blue-bg: rgba(107,159,255,.10);
  --blue-line: rgba(107,159,255,.28);
  --amber: #EAB820;
  --gold: linear-gradient(135deg, #F0D080 0%, #CCA830 100%);
  --red: #FF6B6B;
  --red-bg: rgba(255,107,107,.09);
  --red-line: rgba(255,107,107,.28);
  --green: #6BCB77;
  --green-bg: rgba(107,203,119,.09);
  --green-line: rgba(107,203,119,.28);
  --r: 18px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html, body { background: var(--bg) !important; }
body {
  font-family: Inter, -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  color: var(--t2);
  font-size: 17px; line-height: 1.55; letter-spacing: -.011em;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
  text-wrap: pretty;
}
.page { max-width: 720px; margin: 0 auto; padding: 8px 16px 24px; }

b, strong { color: var(--t1); font-weight: 700; }
.am { color: var(--amber); font-weight: 700; }
p + p { margin-top: 12px; }
svg.i { width: 20px; height: 20px; flex: none; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.h2 {
  font-size: 28px; font-weight: 700; line-height: 1.12; letter-spacing: -.02em; margin-bottom: 14px; text-wrap: balance;
  background: var(--gold); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.lead { font-size: 18px; color: var(--t2); }

/* ——— карточки ——— */
.card { background: var(--card); border: 1px solid var(--line2); border-radius: var(--r); padding: 20px; margin-top: 16px; }
.card-t { display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--t3); margin-bottom: 14px; }
.card-t svg.i { width: 18px; height: 18px; color: var(--blue); }

.page { padding-bottom: 4px; }
svg.i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.ph { padding-top: 22px; border-top: 1px solid var(--line); margin-top: 12px; }
.ph.first { border-top: 0; margin-top: 28px; padding-top: 0; }
.ph-k { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; font-size: 13px; font-weight: 600; color: var(--t3); font-variant-numeric: tabular-nums; }
.ph-n { font-size: 13px; font-weight: 800; letter-spacing: .08em; color: #E3C06A; }
.ph-k .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--t3); }
.ph-k svg.i { width: 15px; height: 15px; }
.ph .h2 { margin: 0; }
.ph .lead { margin-top: 10px; font-size: 16px; line-height: 1.55; }
.map { padding: 18px 18px 8px; margin-top: 4px; }
.map .card-t { margin-bottom: 6px; color: var(--t2); letter-spacing: .02em; text-transform: none; font-size: 15px; }
.map .card-t svg.i { color: #E3C06A; }
.map-sub { font-size: 13px; color: var(--t3); margin-bottom: 8px; }
.toc { list-style: none; }
.toc a { display: flex; align-items: center; gap: 12px; min-height: 48px; padding: 8px 0; border-top: 1px solid var(--line); color: var(--t1); text-decoration: none; -webkit-tap-highlight-color: transparent; }
.toc a:hover .toc-t { color: #F0D080; }
.toc-n { width: 24px; flex: none; font-size: 13px; font-weight: 800; color: #E3C06A; font-variant-numeric: tabular-nums; }
.toc-t { flex: 1; min-width: 0; font-size: 15px; font-weight: 600; line-height: 1.3; transition: color .15s ease-out; }
.toc-t small { display: block; margin-top: 2px; font-size: 12.5px; font-weight: 500; color: var(--t3); }
.toc-d { flex: none; font-size: 13px; color: var(--t3); font-variant-numeric: tabular-nums; }
.toc a > svg.i { width: 16px; height: 16px; color: var(--t3); }
.toc .fin .toc-n { color: var(--blue); }
.toc .fin .toc-n svg.i { width: 18px; height: 18px; }
.sub { display: flex; align-items: center; gap: 10px; margin-top: 10px; font-size: 15px; font-weight: 600; color: var(--t1); }
.sub svg.i { color: #E3C06A; width: 17px; height: 17px; }
.sub span { margin-left: auto; font-size: 13px; font-weight: 500; color: var(--t3); font-variant-numeric: tabular-nums; }
.exm { padding: 16px 18px; }
.exm .card-t { margin-bottom: 12px; }
.exm .card-t svg.i { color: #E3C06A; }
.exm-row { display: flex; flex-wrap: wrap; gap: 10px; }
.exm-b { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 10px 16px; border-radius: 12px; border: 1px solid rgba(240,208,128,.35); background: rgba(240,208,128,.07); color: #F0D080; font-size: 14px; font-weight: 600; text-decoration: none; transition: background-color .15s ease-out, border-color .15s ease-out; }
.exm-b:hover { background: rgba(240,208,128,.14); border-color: rgba(240,208,128,.6); }
.exm-b svg.i { width: 15px; height: 15px; }
.fn { margin-top: 4px; font-size: 12.5px; line-height: 1.5; color: var(--t3); font-style: italic; }
@media (min-width: 640px) { .page { padding: 8px 0 4px; } .h2 { font-size: 34px; } }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
